from pathlib import Path


def replace(path: str, old: str, new: str):
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f"pattern not found in {path}: {old[:120]!r}")
    p.write_text(text.replace(old, new, 1))

p = Path('src/core/folderOrganization.ts')
text = p.read_text()
text = text.replace('  | "one-off-folder"\n  | "uncategorized-concentration";', '  | "one-off-folder";')
text = text.replace('export interface FolderOrganizationAssetRef {', 'export type MetadataHygieneFindingKind = "uncategorized-assets";\n\nexport interface FolderOrganizationAssetRef {')
text = text.replace('export interface FolderOrganizationReport {\n  analyzedAssets: number;\n  findings: FolderOrganizationFinding[];', 'export interface MetadataHygieneFinding {\n  kind: MetadataHygieneFindingKind;\n  workspaceFolderUri: string;\n  workspaceFolderName: string;\n  title: string;\n  reason: string;\n  affectedFolders: string[];\n  affectedAssets: FolderOrganizationAssetRef[];\n}\n\nexport interface FolderOrganizationReport {\n  analyzedAssets: number;\n  findings: FolderOrganizationFinding[];\n  metadataFindings: MetadataHygieneFinding[];')
text = text.replace('  const findings: FolderOrganizationFinding[] = [];\n  const byWorkspace', '  const findings: FolderOrganizationFinding[] = [];\n  const metadataFindings: MetadataHygieneFinding[] = [];\n  const byWorkspace')
text = text.replace('    findings.push(...analyzeWorkspace(workspaceAssets));', '    findings.push(...analyzeWorkspace(workspaceAssets));\n    metadataFindings.push(...analyzeWorkspaceMetadata(workspaceAssets));')
text = text.replace('  return {\n    analyzedAssets: assets.length,\n    findings,', '  metadataFindings.sort((left, right) =>\n    left.workspaceFolderName.localeCompare(right.workspaceFolderName)\n    || left.title.localeCompare(right.title),\n  );\n\n  return {\n    analyzedAssets: assets.length,\n    findings,\n    metadataFindings,')
start = text.index('    const uncategorized = folderAssets.filter((asset) => !asset.assetType);')
end = text.index('    const depth = folderDepth(folder);', start)
text = text[:start] + text[end:]
insert_at = text.index('\nfunction suggestedCharacterTarget')
metadata_fn = '''\nfunction analyzeWorkspaceMetadata(assets: readonly WorkspaceAsset[]): MetadataHygieneFinding[] {\n  const findings: MetadataHygieneFinding[] = [];\n  if (assets.length === 0) return findings;\n  const workspaceFolderUri = assets[0].workspaceFolderUri;\n  const workspaceFolderName = assets[0].workspaceFolderName;\n  const byFolder = groupBy(assets, (asset) => folderOf(asset.asset.relativePath));\n\n  for (const [folder, folderAssets] of byFolder) {\n    const uncategorized = folderAssets.filter((asset) => !asset.assetType);\n    if (\n      folderAssets.length >= FOLDER_ORGANIZATION_THRESHOLDS.uncategorizedMinimumAssets\n      && uncategorized.length >= FOLDER_ORGANIZATION_THRESHOLDS.uncategorizedMinimumAssets\n      && uncategorized.length / folderAssets.length >= FOLDER_ORGANIZATION_THRESHOLDS.uncategorizedMinimumRatio\n    ) {\n      findings.push({\n        kind: "uncategorized-assets",\n        workspaceFolderUri,\n        workspaceFolderName,\n        title: `${displayFolder(folder)} has many Uncategorized assets`,\n        reason: `${uncategorized.length} of ${folderAssets.length} assets (${Math.round(uncategorized.length / folderAssets.length * 100)}%) have no explicit Asset Type. This is a metadata hygiene finding, not a recommendation to move files; no semantic type is inferred.`,\n        affectedFolders: [folder],\n        affectedAssets: uncategorized.map(toAssetRef).sort(compareAssetRef),\n      });\n    }\n  }\n\n  return findings;\n}\n'''
text = text[:insert_at] + metadata_fn + text[insert_at:]
text = text.replace('  return ["scattered-character", "mixed-asset-types", "uncategorized-concentration", "deep-nesting", "one-off-folder"].indexOf(kind);', '  return ["scattered-character", "mixed-asset-types", "deep-nesting", "one-off-folder"].indexOf(kind);')
p.write_text(text)

# Prompt: keep structural and metadata findings explicitly separate.
p = Path('src/core/organizationPrompt.ts')
text = p.read_text()
text = text.replace('  const assetLines = includedAssets.map((asset) => {', '''  const metadataFindingLines = report.metadataFindings.length === 0\n    ? ["- No metadata hygiene findings were detected by the current bounded rules."]\n    : report.metadataFindings.flatMap((finding, index) => [\n      `${index + 1}. ${finding.title}`,\n      `   Workspace: ${finding.workspaceFolderName}`,\n      `   Reason: ${finding.reason}`,\n      `   Folders: ${finding.affectedFolders.map((folder) => folder || "Workspace root").join(", ")}`,\n      `   Affected assets: ${finding.affectedAssets.length}`,\n    ]);\n\n  const assetLines = includedAssets.map((asset) => {''')
text = text.replace('    "- Prefer metadata correction over filesystem changes when the existing folder structure is semantically coherent.",', '    "- Prefer metadata correction over filesystem changes when the existing folder structure is semantically coherent.",\n    "- Metadata Hygiene findings describe missing or inconsistent explicit metadata; they do not imply that files should be moved.",')
text = text.replace('    `Organization findings (${report.findings.length} across ${report.analyzedAssets} analyzed assets):`,\n    ...findingLines,', '    `Folder Organization findings (${report.findings.length} across ${report.analyzedAssets} analyzed assets):`,\n    ...findingLines,\n    "",\n    `Metadata Hygiene findings (${report.metadataFindings.length}):`,\n    ...metadataFindingLines,')
